begin;
alter table public.social_studio_posts add column if not exists image_urls jsonb not null default '[]'::jsonb;
alter table public.social_studio_posts drop constraint if exists social_studio_posts_image_urls_array;
alter table public.social_studio_posts add constraint social_studio_posts_image_urls_array check (jsonb_typeof(image_urls) = 'array');
with campaign as (
  select id from public.marketing_campaigns where campaign_key='hc_apparel_organic_launch' limit 1
), owner as (
  select id from auth.users where lower(email)='heartfamilyco@gmail.com' and email_confirmed_at is not null limit 1
), drafts(id,idem,request_id,title,caption,alt_text,images,scheduled_at,destination) as (values
('63000000-0000-4000-8000-000000000001'::uuid,'73000000-0000-4000-8000-000000000001'::uuid,'83000000-0000-4000-8000-000000000001'::uuid,'Your next favorite crew.',E'Your next favorite crew starts with the American Apparel RF494 ReFlex Fleece Crewneck 💚 Pick your blank, then make it yours.\n\nShop the blank: https://www.ilovehcapparel.net/ProductDetail?id=9a6a7605-e6bb-44fd-92e4-7df6aca7b68e\n\nWant DTF or DTG printing? Send us your design for a separate printing quote.\n\n#HCApparel #AmericanApparel #BlankApparel #Crewneck #CustomPrinting','A model wearing an American Apparel RF494 ReFlex Fleece crewneck beside “Your Next Favorite Crew.”',jsonb_build_array('https://www.ilovehcapparel.net/marketing/campaigns/6pm/rf494-crewneck.png'),'2026-10-19 18:00:00-04'::timestamptz,'https://www.ilovehcapparel.net/ProductDetail?id=9a6a7605-e6bb-44fd-92e4-7df6aca7b68e'),
('63000000-0000-4000-8000-000000000002','73000000-0000-4000-8000-000000000002','83000000-0000-4000-8000-000000000002','Your next go-to hoodie.',E'Your next go-to hoodie starts here 💚 Pick your American Apparel RF498 blank, then bring your design to life.\n\nShop the blank: https://www.ilovehcapparel.net/ProductDetail?id=bf4b8a0f-4a7e-4126-8afa-ed6685df7f4a\n\nWant DTF or DTG printing? Send us your design for a separate printing quote.\n\n#HCApparel #AmericanApparel #BlankHoodie #DTFPrinting #DTGPrinting','A model wearing a brown American Apparel RF498 ReFlex Fleece hoodie in an HC Apparel campaign graphic.',jsonb_build_array('https://www.ilovehcapparel.net/marketing/campaigns/6pm/rf498-brown-hoodie.png'),'2026-10-22 18:00:00-04','https://www.ilovehcapparel.net/ProductDetail?id=bf4b8a0f-4a7e-4126-8afa-ed6685df7f4a'),
('63000000-0000-4000-8000-000000000003','73000000-0000-4000-8000-000000000003','83000000-0000-4000-8000-000000000003','Your next favorite hoodie.',E'Storm Blue is an easy way to add some color without doing too much 💙 Start with the Independent Trading Co. SS4500 midweight hoodie and make it yours.\n\nShop the blank: https://www.ilovehcapparel.net/ProductDetail?id=36352045-4de0-4ad1-8366-219aaa65182b\n\nNeed DTF or DTG printing? Send us your design for a separate printing quote.\n\n#HCApparel #IndependentTradingCo #BlankHoodie #DTFPrinting #DTGPrinting','A model wearing an Independent Trading Co SS4500 Storm Blue blank hoodie.',jsonb_build_array('https://www.ilovehcapparel.net/marketing/campaigns/6pm/ss4500-storm-blue.png'),'2026-10-26 18:00:00-04','https://www.ilovehcapparel.net/ProductDetail?id=36352045-4de0-4ad1-8366-219aaa65182b'),
('63000000-0000-4000-8000-000000000004','73000000-0000-4000-8000-000000000004','83000000-0000-4000-8000-000000000004','Your next go-to layer.',E'Need an easy layer for work, teams, or everyday wear? Compare the adidas A721 and Gildan 18810 quarter-zips, then choose the blank that fits your idea.\n\nShop adidas A721: https://www.ilovehcapparel.net/ProductDetail?id=4e9ae0c7-243e-44c6-a90c-47042b949bd2\n\nShop Gildan 18810: https://www.ilovehcapparel.net/ProductDetail?id=014d48c8-1a3f-406b-817c-4d49782af796\n\nDTF or DTG printing is quoted separately after garment and artwork review.\n\n#HCApparel #QuarterZip #BlankApparel #CustomPrinting','Two models wearing adidas A721 and Gildan 18810 quarter-zip blank garments.',jsonb_build_array('https://www.ilovehcapparel.net/marketing/campaigns/6pm/quarter-zip-duo.png'),'2026-10-29 18:00:00-04','https://www.ilovehcapparel.net/ShopGarments'),
('63000000-0000-4000-8000-000000000005','73000000-0000-4000-8000-000000000005','83000000-0000-4000-8000-000000000005','Find your print fit.',E'Not sure where your design should go? Save these two placement guides for chest, full-front, hood, sleeve, upper-back, and hem ideas.\n\nThese are starting points—not one-size-fits-all. Final print size depends on the garment, artwork, and placement.\n\nBrowse blanks: https://www.ilovehcapparel.net/ShopGarments\n\nNeed DTF or DTG printing? Send us your design for a separate quote: https://www.ilovehcapparel.net/PrintSupport\n\n#HCApparel #PrintPlacement #DTFPrinting #DTGPrinting #CustomApparel','Two HC Apparel print placement guides covering chest, full-front, hood, sleeve, upper-back, and hem positions.',jsonb_build_array('https://www.ilovehcapparel.net/marketing/campaigns/6pm/print-fit-hoodie.png','https://www.ilovehcapparel.net/marketing/campaigns/6pm/print-fit-placement.png'),'2026-11-02 18:00:00-05','https://www.ilovehcapparel.net/PrintSupport'),
('63000000-0000-4000-8000-000000000006','73000000-0000-4000-8000-000000000006','83000000-0000-4000-8000-000000000006','Little crew. Big personality.',E'Little crew. Big personality 💚 Start with the Rabbit Skins 3317 toddler fleece crewneck in Vintage Camo for their next idea.\n\nShop the blank: https://www.ilovehcapparel.net/ProductDetail?id=81be162f-d4ad-4392-a2c7-36314bc2542a\n\nDTF or DTG printing is available through a separate printing quote.\n\n#HCApparel #RabbitSkins #ToddlerStyle #BlankApparel #CustomPrinting','Two views of a child wearing the Rabbit Skins 3317 toddler fleece crewneck in Vintage Camo.',jsonb_build_array('https://www.ilovehcapparel.net/marketing/campaigns/6pm/rabbit-skins-3317-camo.png'),'2026-11-05 18:00:00-05','https://www.ilovehcapparel.net/ProductDetail?id=81be162f-d4ad-4392-a2c7-36314bc2542a')
)
insert into public.social_studio_posts(id,idempotency_key,created_by,campaign_id,platform,content_type,brand,product_name,tone,audience,caption_length,cta,include_hashtags,notes,image_url,image_urls,image_mode,caption,status,workflow_status,post_title,post_description,alt_text,keywords,destination_url,scheduled_at,schedule_timezone,verification_snapshot)
select d.id,d.idem,o.id,c.id,'facebook','Product Promo','HC Apparel',d.title,'natural, direct, friendly, and conversational','customers shopping blanks or planning custom printing','medium','Shop blank garments',true,'Exact version approved in Codex conversation; RF494 artwork mismatch explicitly accepted without describing Sage as available.',d.images->>0,d.images,'artwork',d.caption,'draft','Draft',d.title,d.caption,d.alt_text,array['HC Apparel','blank apparel','DTF printing','DTG printing'],d.destination,d.scheduled_at,'America/New_York',jsonb_build_object('approval_channel','codex_conversation','six_pm_batch',true,'image_count',jsonb_array_length(d.images)) from drafts d cross join campaign c cross join owner o on conflict(idempotency_key) do nothing;
with drafts(post_id,request_id) as (values
('63000000-0000-4000-8000-000000000001'::uuid,'83000000-0000-4000-8000-000000000001'::uuid),('63000000-0000-4000-8000-000000000002','83000000-0000-4000-8000-000000000002'),('63000000-0000-4000-8000-000000000003','83000000-0000-4000-8000-000000000003'),('63000000-0000-4000-8000-000000000004','83000000-0000-4000-8000-000000000004'),('63000000-0000-4000-8000-000000000005','83000000-0000-4000-8000-000000000005'),('63000000-0000-4000-8000-000000000006','83000000-0000-4000-8000-000000000006'))
insert into public.marketing_approval_requests(id,page_key,request_type,source_kind,source_material,proposed_content,image_url,context,content_version,content_hash,status,scheduled_at,linked_post_id,idempotency_key,created_by)
select d.request_id,'hc_apparel','post','photo','Owner-supplied finished HC Apparel artwork.',p.post_description,p.image_url,jsonb_build_object('post_title',p.post_title,'destination_url',p.destination_url,'proposed_posting_time',p.scheduled_at,'timezone','America/New_York','alt_text',p.alt_text,'image_urls',p.image_urls,'approval_channel','codex_conversation'),1,md5(concat_ws('|','hc_apparel','post',p.post_description,p.image_urls::text)),'pending',p.scheduled_at,p.id,d.request_id,p.created_by from drafts d join public.social_studio_posts p on p.id=d.post_id on conflict(idempotency_key) do nothing;
commit;
